function renderGreeting() {
  const hour = new Date().getHours();
  let greeting = '早上好';
  if (hour >= 12 && hour < 14) greeting = '中午好';
  else if (hour >= 14 && hour < 18) greeting = '下午好';
  else if (hour >= 18 || hour < 6) greeting = '晚上好';
  // 【2026-09-15 空判修复】仅首页有 #greetingText，其他页未判空会抛错打断 renderHome 后续渲染
  var _gt = document.getElementById('greetingText');
  if (_gt) _gt.textContent = greeting;
}

// ========== T16 倒计时日期规范化与天数计算（2026-09-12 P0-A） ==========
// 存量脏数据形如 '202612-02-01'，new Date 宽松解析成公元 202612 年 → 算出 7 万多天。
// 规则：仅接受 YYYY-MM-DD / YYYY.MM.DD / YYYY/MM/DD / YYYY年MM月DD日（含无分隔符变体），
// 月 1-12、日 1-31，并做 Date 回验（如 2 月 30 日会因 Date 进位被拒绝）。返回 YYYY-MM-DD 或 null。
function normalizeCountdownDate(raw) {
  if (typeof raw !== 'string') return null;
  const m = raw.trim().match(/^(\d{4})[-./年]?(\d{1,2})[-./月]?(\d{1,2})日?$/);
  if (!m) return null;
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
  const dt = new Date(y, mo - 1, d);
  if (dt.getFullYear() !== y || dt.getMonth() !== mo - 1 || dt.getDate() !== d) return null;
  return y + '-' + String(mo).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}
// 严格按本地时区计算「今天到目标日」的天数差；非法输入返回 null（显示 '--'，绝不显示假天数）
function countdownDays(dateStr) {
  if (typeof dateStr !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return null;
  const m = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  const target = new Date(y, mo - 1, d);
  // BUG-2 修复：Date 回验（2 月 30 日 / 13 月会被 Date 进位吞掉，必须拦截）
  if (isNaN(target.getTime()) || target.getFullYear() !== y || target.getMonth() !== mo - 1 || target.getDate() !== d) return null;
  const now = new Date();
  const today0 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  return Math.floor((target.getTime() - today0.getTime()) / 86400000);
}

function renderCountdowns() {
  const row = document.getElementById('countdownRow');
  let html = '';
  // 排序：置顶优先，然后按规范化日期时间戳（无法解析的排最后）
  const ts = (d) => {
    const n = normalizeCountdownDate(d.date);
    return n ? new Date(Number(n.slice(0, 4)), Number(n.slice(5, 7)) - 1, Number(n.slice(8, 10))).getTime() : Infinity;
  };
  const sorted = [...appData.countdowns].sort((a, b) => {
    // BUG-2 配套修复：pinned 可能是 undefined，直接相减会得到 NaN 导致排序未定义
    const ap = a.pinned ? 1 : 0, bp = b.pinned ? 1 : 0;
    if (ap !== bp) return bp - ap;
    return ts(a) - ts(b);
  });
  sorted.forEach(cd => {
    const days = countdownDays(cd.date);
    html += `
      <div class="countdown-card" style="--cd-color:${cd.color}">
        <div class="countdown-actions">
          <div class="countdown-btn" onclick="editCountdown(${cd.id})" title="编辑">${icSpan('pencil', 14)}</div>
          <div class="countdown-btn" onclick="deleteCountdown(${cd.id})" title="删除">${icSpan('trash', 14)}</div>
        </div>
        <div class="countdown-name">${cd.name}${cd.pinned ? ' ' + icSpan('pin', 12) : ''}</div>
        <div class="countdown-days">${days == null ? '--' : (days > 0 ? days : 0)}<span class="unit">天</span></div>
        <div class="countdown-date">${cd.date}</div>
      </div>
    `;
  });
  // 添加按钮
  html += `
    <div class="countdown-card countdown-add" onclick="openCountdownModal()">
      <div class="add-icon">+</div>
      <div>添加倒计时</div>
    </div>
  `;
  row.innerHTML = html;
  if (window.lucideAutoRender) window.lucideAutoRender();
}

function renderTasks() {
  // 【R37】内置任务已移除：无任务时在触碰 #taskList 之前直接返回。
  // 严禁走到 list.innerHTML 赋值——#taskList 由 学习工作台.html xtHomeEnhanceJs
  // 渲染自定义任务，整块重写（即使是空串）会误删自定义任务节点。
  if (!appData.tasks || !appData.tasks.length) return;
  const list = document.getElementById('taskList');
  let html = '';
  appData.tasks.forEach(task => {
    html += `
      <div class="task-item ${task.done ? 'done' : ''}" onclick="toggleTask(${task.id})">
        <div class="task-checkbox">✓</div>
        <div class="task-info">
          <div class="task-name">${task.name}</div>
          <div class="task-meta">${getModuleName(task.module)}</div>
        </div>
        <div class="task-progress">${task.progress}</div>
      </div>
    `;
  });
  list.innerHTML = html;
}

function getModuleName(module) {
  const names = { cet: '四级备考', exam: '央国企笔试', comm: '高情商表达', interview: '商务礼仪面试', ppt: 'PPT训练' };
  return names[module] || module;
}

function toggleTask(id) {
  const task = appData.tasks.find(t => t.id === id);
  if (task) {
    task.done = !task.done;
    saveData();
    renderTasks();
    updateTopbarStats();
    updateGoalProgress();
    if (task.done) {
      // T18②：完成首页任务也算一次「学习动作」，推进全局连续打卡
      try { window.Streak && window.Streak.bump(); } catch (e) { /* 静默 */ }
      showToast('✅ 任务完成，太棒了！');
    }
  }
}

function resetTasks() {
  appData.tasks.forEach(t => t.done = false);
  saveData();
  renderTasks();
  updateTopbarStats();
  showToast('今日任务已重置');
}

// 开始今天的学习
function startTodayLearning() {
  var pending = (appData.tasks || []).filter(function(t) { return !t.done; });
  var cta = document.getElementById('ctaSubtitle');
  if (pending.length === 0) {
    if (cta) cta.textContent = '🎉 今日任务全部完成！';
    showToast('🎉 今日任务全部完成！');
    return;
  }
  var t = pending[0];
  if (cta) cta.textContent = '正在进入：' + t.title;
  if (t.page) { switchPage(t.page); } else if (t.url) { location.href = t.url; } else { showToast('开始：' + t.title); }
}

function renderStats() {
  var stats = appData.stats || {};
  var summ = getStudySummary();

  // 总学习时长（小时）：优先取本地真实统计（study-stats.js，分钟→小时），
  // 与 appData 取较大值（不归零），都缺省时自然为 0，不显示假数据。
  var appHours = stats.totalHours || 0;
  var statHours = (summ && typeof summ.totalMinutes === 'number')
    ? Math.round(summ.totalMinutes / 60) : 0;
  var totalHours = Math.max(appHours, statHours);

  // 做题数 / 正确率：来自做题记录；无记录即 0（不造假）
  var totalQuestions = stats.totalQuestions || 0;
  var correctQuestions = stats.correctQuestions || 0;
  const acc = totalQuestions > 0 ? Math.round(correctQuestions / totalQuestions * 100) : 0;

  // 连续打卡：全局 Streak（单一口径）与 appData/study-stats 取较大值，不归零（T18②）
  var streak = Math.max(getConvergedStreak(), (summ && summ.streak) || 0);

  setStatText('totalHours', totalHours);
  setStatText('totalQuestions', totalQuestions);
  setStatText('accuracy', acc + '%');
  setStatText('streakDisplay', streak);

  // 空态：完全没有任何学习记录时给出引导文案（有记录则隐藏）
  var hasData = (summ && summ.hasData) || totalQuestions > 0 || totalHours > 0 || streak > 0;
  var hint = document.getElementById('statsEmptyHint');
  if (hint) hint.style.display = hasData ? 'none' : 'block';

  renderWeekChart(summ);
  updateGoalProgress();
}

/* 读取本地学习统计（study-stats.js）。不可用时返回 null（file:// 未加载该文件时降级）。 */
function getStudySummary() {
  if (window.StudyStats && typeof window.StudyStats.getSummary === 'function') {
    try { return window.StudyStats.getSummary(); } catch (e) { return null; }
  }
  return null;
}

function setStatText(id, value) {
  var el = document.getElementById(id);
  if (el) el.textContent = value;
}

function updateGoalProgress() {
  const doneCount = appData.tasks.filter(t => t.done).length;
  const total = appData.tasks.length;
  const percent = total > 0 ? Math.round(doneCount / total * 100) : 0;
  // 更新环形进度
  const ring = document.getElementById('goalRing');
  const goalPercent = document.getElementById('goalPercent');
  const goalText = document.getElementById('goalText');
  if (ring) {
    const circumference = 2 * Math.PI * 28; // ~176
    ring.style.strokeDashoffset = circumference * (1 - percent / 100);
  }
  if (goalPercent) goalPercent.textContent = percent + '%';
  if (goalText) goalText.textContent = `已完成 ${doneCount}/${total} 个任务`;
  // 更新成就徽章
  const badges = document.querySelectorAll('.achievement-badge');
  if (badges.length >= 4) {
    // 新手徽章：始终解锁（首次使用）
    badges[0].classList.remove('locked');
    // 3连击：连续打卡>=3天
    if (appData.stats.streakDays >= 3) badges[1].classList.remove('locked');
    // 刷题达人：完成>=10题
    if (appData.stats.totalQuestions >= 10) badges[2].classList.remove('locked');
    // 口语新星：这个暂时根据做题数判断，后续接入口语练习记录
    if (appData.stats.totalQuestions >= 5) badges[3].classList.remove('locked');
  }
}

function renderWeekChart(summ) {
  const chart = document.getElementById('weekChart');
  if (!chart) return;
  const weekdays = ['一', '二', '三', '四', '五', '六', '日'];
  // 真实数据来源：study-stats.js 的本周（周一→周日）每日分钟数；
  // 无统计底座时全 0 —— 不再回退到任何模拟数组（无假数据）。
  const weekData = [0, 0, 0, 0, 0, 0, 0];
  if (summ && Object.prototype.toString.call(summ.week) === '[object Array]') {
    for (let w = 0; w < 7; w++) {
      const cell = summ.week[w];
      weekData[w] = (cell && typeof cell.minutes === 'number') ? cell.minutes : 0;
    }
  }
  const hasWeekData = weekData.some(function (v) { return v > 0; });
  const today = new Date().getDay();
  const todayIdx = today === 0 ? 6 : today - 1; // 周一为0
  const maxVal = Math.max.apply(null, weekData.concat([60]));
  let html = '';
  for (let i = 0; i < 7; i++) {
    const val = weekData[i];
    const heightPct = (val / maxVal) * 100;
    const isToday = i === todayIdx;
    html += `
      <div class="week-bar-item">
        <div class="week-bar ${isToday ? 'today' : ''}" style="height:${heightPct}%">
          ${val > 0 ? `<span class="week-bar-value">${val}</span>` : ''}
        </div>
        <div class="week-bar-label" style="${isToday ? 'color:var(--accent);font-weight:700' : ''}">${weekdays[i]}${isToday ? '·今' : ''}</div>
      </div>
    `;
  }
  if (!hasWeekData) html += '<div class="week-chart-empty">还没有学习记录，去学一章吧</div>';
  chart.innerHTML = html;
}

// ========== T01（批次三 R1）：首页真实化 —— 纯计算函数（与渲染解耦） ==========
// 旧字段 moduleProgress/weakPoints/recentLearning 已废弃（见上方注释），不再参与渲染。
// 【2026-09-15 重构·去除写死分母】原表里 exam:100 / comm:10 / ppt:10 是题库只有几百题时拍的
// 分母。题库涨到「行测 4488 + 申论 100」后，写死分母会让「已学 200 题 / 100 = 200% → 夹到 100%」
// 这类名不副实的进度。现一律在运行时取真实总量（见 computeModuleProgress / computeHomeModules），
// 取不到就是 0 → 走空态，绝不编造分母。本对象仅保留为 interviewProgressTarget() 的兜底回退。
const MODULE_PROGRESS_TARGET = {
  cet: 0, exam: 0, comm: 0, interview: 0, ppt: 0
};

// ===== 首页「各模块进度」卡片：模块清单（2026-09-15 重构，覆盖全部学习模块）=====
// 设计说明（为什么是这 12 张卡）：
//  · 行测五大模块与 EXAM_BANK 的 type 不是一对一 —— 图形推理 / 定义判断 / 类比推理 / 逻辑判断
//    在考试学上同属「判断推理」，必须按下表归并，否则判断推理会漏统计这 4 个题型。
//  · 央国企笔试.html 的行测入口就是 exam-center（同一套 EXAM_BANK），不再重复出卡。
//  · 错题本没有「已攻克」数据源（wrongQuestions 只增不减），出卡必然恒 0% 空转，故不列入。
//  · 四级备考.html 只有任务清单与目标日，没有可计量的内容库，同样不列入（不造假数据）。
const XT_EXAM_MODULE_TYPES = {
  '数量关系': ['数量关系'],
  '言语理解': ['言语理解'],
  '常识判断': ['常识判断'],
  '判断推理': ['判断推理', '图形推理', '定义判断', '类比推理', '逻辑判断'],
  '资料分析': ['资料分析']
};

// 内容库型模块：viewedContent 的 key ↔ 题库常量 ↔ 跳转页 ↔ 量词
const XT_LIB_MODULES = [
  { id: 'iv-questions', name: '面试题库', icon: 'users',          page: 'iv-questions', ck: 'ivQuestions', lenKey: 'iv',     unit: '条' },
  { id: 'etiquette',    name: '商务礼仪', icon: 'handshake',      page: 'etiquette',    ck: 'etiquette',   lenKey: 'eti',    unit: '条' },
  { id: 'ppt-layouts',  name: 'PPT版式',  icon: 'presentation',   page: 'ppt-layouts',  ck: 'pptLayouts',  lenKey: 'ppt',    unit: '条' },
  { id: 'comm-scenes',  name: '场景话术', icon: 'message-square', page: 'comm-scenes',  ck: 'commScenes',  lenKey: 'scene',  unit: '条' },
  { id: 'comm-quotes',  name: '万能金句', icon: 'quote',          page: 'comm-quotes',  ck: 'commQuotes',  lenKey: 'quote',  unit: '条' }
];

// 行测五子模块图标（与 XT_EXAM_MODULE_TYPES 同序）
const XT_EXAM_MODULE_ICONS = {
  '数量关系': 'calculator', '言语理解': 'book-open', '常识判断': 'lightbulb',
  '判断推理': 'puzzle', '资料分析': 'chart-bar'
};

// 运行时读题库常量长度。注意：这些常量是 const，声明在本函数之后（TDZ），
// 顶层直接引用会抛 ReferenceError，故必须放在函数体内 + try 兜底（与 interviewProgressTarget 同理）。
function libLen(lenKey) {
  try {
    if (lenKey === 'cet')   return (typeof CET_VOCAB !== 'undefined' && CET_VOCAB) ? CET_VOCAB.length : 0;
    if (lenKey === 'iv')    return (typeof INTERVIEW_QUESTIONS !== 'undefined' && INTERVIEW_QUESTIONS) ? INTERVIEW_QUESTIONS.length : 0;
    if (lenKey === 'eti')   return (typeof ETIQUETTE_DATA !== 'undefined' && ETIQUETTE_DATA) ? ETIQUETTE_DATA.length : 0;
    if (lenKey === 'ppt')   return (typeof PPT_LAYOUTS !== 'undefined' && PPT_LAYOUTS) ? PPT_LAYOUTS.length : 0;
    if (lenKey === 'scene') return (typeof COMM_SCENES !== 'undefined' && COMM_SCENES) ? COMM_SCENES.length : 0;
    if (lenKey === 'quote') return (typeof COMM_QUOTES !== 'undefined' && COMM_QUOTES) ? COMM_QUOTES.length : 0;
    if (lenKey === 'exam')  return (typeof EXAM_BANK !== 'undefined' && EXAM_BANK) ? EXAM_BANK.length : 0;
  } catch (e) { return 0; }
  return 0;
}

// EXAM_BANK 里属于该行测模块的题数（实时数，不写死；异步分片合并后下一次渲染自动跟上）
function countExamBankByTypes(types) {
  var n = 0;
  try {
    if (typeof EXAM_BANK === 'undefined' || !EXAM_BANK) return 0;
    for (var i = 0; i < EXAM_BANK.length; i++) {
      var q = EXAM_BANK[i];
      if (q && types.indexOf(q.type) >= 0) n++;
    }
  } catch (e) { /* TDZ / 脏数据：按已数到的返回 */ }
  return n;
}

// 该行测模块的真实做题数 / 正确数（∑ 下属题型）
function examModuleStat(types) {
  var total = 0, correct = 0;
  try {
    var etp = (appData && appData.examTypeProgress) || {};
    types.forEach(function (t) {
      var v = etp[t];
      if (!v) return;
      total += Number(v.total) || 0;
      correct += Number(v.correct) || 0;
    });
  } catch (e) {}
  return { done: total, correct: correct };
}

// 申论：独立页（申论刷题.html）+ 独立存储（localStorage 'shenlun_answers'），不进 appData
function getShenlunAnswers() {
  try {
    var raw = localStorage.getItem('shenlun_answers');
    var o = raw ? JSON.parse(raw) : null;
    return (o && typeof o === 'object' && !Array.isArray(o)) ? o : {};
  } catch (e) { return {}; }
}

// 申论题库总量：优先已加载的题库，其次首页异步 fetch 后缓存下来的条数；取不到返回 0（走空态，不编造）
function getShenlunBankTotal() {
  try {
    if (typeof INLINE_SHENLUN_BANK !== 'undefined' && INLINE_SHENLUN_BANK && INLINE_SHENLUN_BANK.length) return INLINE_SHENLUN_BANK.length;
  } catch (e) {}
  try {
    if (typeof SL_QUESTIONS !== 'undefined' && SL_QUESTIONS && SL_QUESTIONS.length) return SL_QUESTIONS.length;
  } catch (e) {}
  try {
    var raw = localStorage.getItem('shenlun_questions');
    if (raw) { var a = JSON.parse(raw); if (a && a.length) return a.length; }
  } catch (e2) {}
  try {
    var c = Number(localStorage.getItem(lsKey('xt_shenlun_total')));
    if (c > 0) return c;
  } catch (e3) {}
  return 0;
}

function shenlunStat() {
  var done = 0, finished = 0, lastTs = 0;
  try {
    var m = getShenlunAnswers();
    Object.keys(m).forEach(function (id) {
      var a = m[id];
      if (!a) return;
      if (String(a.answer || '').replace(/\s/g, '')) done++;
      if (a.status === '已完成') finished++;
      var t = Date.parse(a.updated || '') || 0;
      if (t > lastTs) lastTs = t;
    });
  } catch (e) {}
  return { done: done, finished: finished, lastTs: lastTs, total: getShenlunBankTotal() };
}

// 一条行为日志 → 归属哪些模块卡（行测按题目 type 归并到五大模块）
function activityLogModuleKeys(it) {
  var keys = [];
  var type = it.type || '';
  if (type === 'vocab' || type === 'listen') return ['cet'];
  var libMap = {
    commScenes: 'comm-scenes', commQuotes: 'comm-quotes',
    ivQuestions: 'iv-questions', pptLayouts: 'ppt-layouts', etiquette: 'etiquette'
  };
  if (libMap[type]) return [libMap[type]];
  if (type === 'exam' || type === 'fav') {
    var q = findExamById(Number(it.ref));
    if (q && q.type) {
      Object.keys(XT_EXAM_MODULE_TYPES).forEach(function (m) {
        if (XT_EXAM_MODULE_TYPES[m].indexOf(q.type) >= 0) keys.push('exam:' + m);
      });
    }
  }
  return keys;
}

// 各模块「最近一次学习」时间戳（0 = 无）
function buildModuleLastTsMap() {
  var map = {};
  try {
    var log = (appData && Array.isArray(appData.activityLog)) ? appData.activityLog : [];
    log.forEach(function (it) {
      if (!it) return;
      var ts = Number(it.t) || 0;
      if (!ts) return;
      activityLogModuleKeys(it).forEach(function (k) {
        if (!map[k] || ts > map[k]) map[k] = ts;
      });
    });
  } catch (e) {}
  // 申论页不在 activityLog 里写日志，改用其答案自带的 updated 时间
  try {
    var t = shenlunStat().lastTs;
    if (t) map['shenlun'] = t;
  } catch (e2) {}
  return map;
}

// 错题按题型的计数：wrongQuestions 只存 id，需回表 EXAM_BANK 还原 type。
// 一次建索引（O(题库)）再统计（O(错题)），避免逐题线性查找。
function buildWrongTypeCounts() {
  var c = {};
  try {
    var wq = (appData && Array.isArray(appData.wrongQuestions)) ? appData.wrongQuestions : [];
    if (!wq.length) return c;
    var bank = (typeof EXAM_BANK !== 'undefined' && EXAM_BANK) ? EXAM_BANK : [];
    var tmap = {};
    for (var i = 0; i < bank.length; i++) tmap[bank[i].id] = bank[i].type;
    for (var j = 0; j < wq.length; j++) {
      var t = tmap[Number(wq[j])];
      if (t) c[t] = (c[t] || 0) + 1;
    }
  } catch (e) { /* 静默：错题统计失败不影响卡片渲染 */ }
  return c;
}

// 组装首页全部模块卡（纯计算，不碰 DOM）
function computeHomeModules() {
  var lastMap = buildModuleLastTsMap();
  var wrongMap = buildWrongTypeCounts();
  var out = [];
  try {
    Object.keys(XT_EXAM_MODULE_TYPES).forEach(function (name) {
      var types = XT_EXAM_MODULE_TYPES[name];
      var st = examModuleStat(types);
      var w = 0;
      try { types.forEach(function (t) { w += (wrongMap[t] || 0); }); } catch (e0) {}
      out.push({
        id: 'exam:' + name, name: name, icon: XT_EXAM_MODULE_ICONS[name] || 'package',
        page: 'exam-center', group: '行测', unit: '题', hasRate: true,
        done: st.done, correct: st.correct, total: countExamBankByTypes(types),
        finished: 0, wrong: w, lastTs: lastMap['exam:' + name] || 0
      });
    });
  } catch (e1) {}
  try {
    var sl = shenlunStat();
    out.push({
      id: 'shenlun', name: '申论', icon: 'file-text', page: 'shenlun', group: '申论',
      unit: '题', hasRate: false,
      done: sl.done, correct: 0, total: sl.total, finished: sl.finished, wrong: 0, lastTs: sl.lastTs
    });
  } catch (e2) {}
  try {
    var vl = (appData && Array.isArray(appData.vocabLearned)) ? appData.vocabLearned.length : 0;
    out.push({
      id: 'cet', name: '四级词汇', icon: 'book', page: 'cet-vocab', group: '英语',
      unit: '词', hasRate: false,
      done: vl, correct: 0, total: libLen('cet'), finished: 0, wrong: 0, lastTs: lastMap['cet'] || 0
    });
  } catch (e3) {}
  try {
    XT_LIB_MODULES.forEach(function (d) {
      var done = (((appData && appData.viewedContent) || {})[d.ck] || []).length;
      out.push({
        id: d.id, name: d.name, icon: d.icon, page: d.page, group: '内容库',
        unit: d.unit, hasRate: false,
        done: done, correct: 0, total: libLen(d.lenKey), finished: 0, wrong: 0, lastTs: lastMap[d.id] || 0
      });
    });
  } catch (e4) {}
  return out;
}

// 卡片状态：'empty' 未开始 | 'few' 数据不足（1~4）| 'ok' 正常
function homeModuleState(m) {
  var d = Number(m && m.done) || 0;
  if (d <= 0) return 'empty';
  if (d < 5) return 'few';
  return 'ok';
}

// 完成度百分比（分母 ≤0 → 0，永不 NaN）
function homeModulePercent(m) {
  var d = Number(m && m.done) || 0;
  var t = Number(m && m.total) || 0;
  return pct(d, t);
}

// 正确率（只有行测这类「有对错」的模块才有）；数据不足返回 null
function homeModuleRate(m) {
  if (!m || !m.hasRate) return null;
  var d = Number(m.done) || 0;
  if (d <= 0) return null;
  return Math.round((Number(m.correct) || 0) / d * 100);
}

// 百分比计算：分母 ≤0 一律返回 0（杜绝 NaN / Infinity），结果夹在 0-100
function pct(n, d) {
  n = Number(n) || 0;
  d = Number(d) || 0;
  return d > 0 ? Math.min(100, Math.max(0, Math.round(n / d * 100))) : 0;
}

// 面试模块分母：优先取 INTERVIEW_QUESTIONS 的真实长度。
// 注意：INTERVIEW_QUESTIONS 是下方（2867 行附近）声明的 const，此处若在顶层直接引用会踩 TDZ 抛错，
// 因此必须在函数体内「运行时」读取；取不到时回退 MODULE_PROGRESS_TARGET.interview。
function interviewProgressTarget() {
  var n = 0;
  try {
    if (typeof INTERVIEW_QUESTIONS !== 'undefined' && INTERVIEW_QUESTIONS && INTERVIEW_QUESTIONS.length) {
      n = INTERVIEW_QUESTIONS.length;
    }
  } catch (e) { n = 0; }
  return n > 0 ? n : (MODULE_PROGRESS_TARGET.interview || 0);
}

// 计算五模块实时进度（0-100 数值）；任一模块推导总数为 0 → 0（渲染层显示「未开始」）
// 【2026-09-15】分母全部改为运行时真实题库长度（原 exam:100 / comm:10 / ppt:10 已废弃）。
// 本函数为兼容旧验收脚本保留；首页卡片实际用的是覆盖全模块的 computeHomeModules()。
function computeModuleProgress() {
  var res = { cet: 0, exam: 0, comm: 0, interview: 0, ppt: 0 };
  try {
    var learned = (appData.vocabLearned || []).length;
    res.cet = pct(learned, libLen('cet'));
  } catch (e) {}
  try {
    var sum = 0, etp = appData.examTypeProgress || {};
    Object.keys(etp).forEach(function (k) { sum += (etp[k].total || 0); });
    res.exam = pct(sum, libLen('exam'));
  } catch (e) {}
  try {
    var commN = ((appData.viewedContent || {}).commScenes || []).length;
    res.comm = pct(commN, libLen('scene'));
  } catch (e) {}
  try {
    // 面试进度 = 已看过的面试题库条目 / 面试题库总数（全仓无"面试场次"记录入口，故不可用 interviewDone）
    var ivN = (((appData.viewedContent || {}).ivQuestions) || []).length;
    var ivT = interviewProgressTarget();
    res.interview = pct(ivN, ivT > 0 ? ivT : libLen('iv'));
  } catch (e) {}
  try {
    var pptN = ((appData.viewedContent || {}).pptLayouts || []).length;
    res.ppt = pct(pptN, libLen('ppt'));
  } catch (e) {}
  return res;
}

// 薄弱点：① examTypeProgress 筛「做题≥5 且 正确率<60%」；② 错题本按题型聚合，错题≥3 且该题型做过≥5 的
// 也算薄弱（去重补充，数据不足 total<5 不展示）。按正确率升序取前 3，条目带 wrong=错题数供文案使用。
function computeWeakPoints() {
  var list = [];
  var etp = {};
  try { etp = appData.examTypeProgress || {}; } catch (e0) { etp = {}; }
  try {
    Object.keys(etp).forEach(function (k) {
      var v = etp[k]; if (!v) return;
      var total = v.total || 0;
      if (total >= 5 && total > 0) {
        var rate = (v.correct || 0) / total;
        if (rate < 0.6) list.push({ title: k, rate: rate, module: 'exam', sub: v.sub || '', wrong: 0 });
      }
    });
  } catch (e) {}
  // ② 错题本维度：wrongQuestions 只存题 id，经 findExamById 还原标题的 type 聚合
  try {
    var wrongCount = {};
    (appData.wrongQuestions || []).forEach(function (id) {
      var q = findExamById(Number(id));
      if (q && q.type) wrongCount[q.type] = (wrongCount[q.type] || 0) + 1;
    });
    Object.keys(wrongCount).forEach(function (k) {
      var total = (etp[k] && etp[k].total) || 0;
      if (wrongCount[k] >= 3 && total >= 5 && !list.some(function (w) { return w.title === k; })) {
        var rate = (etp[k].correct || 0) / total;
        list.push({ title: k, rate: rate, module: 'exam', sub: (etp[k] && etp[k].sub) || '', wrong: wrongCount[k] });
      }
    });
  } catch (e2) {}
  try { list.sort(function (a, b) { return a.rate - b.rate; }); } catch (e3) {}
  return list.slice(0, 3);
}

// ========== T03（批次三 R1-3）：行为日志 activityLog（环形 200 条） ==========
// 背景：wrongQuestions / favoriteQuestions 只存题 id 无时间戳，vocabRecords / examRecords 只到日期，
// 做不出「3 分钟前」这类相对时间，故新增带 epoch ms 的行为日志。只追加、随调用方此后的 saveData() 落盘。
const ACTIVITY_LOG_MAX = 200; // 环形上限，超出丢弃最旧，体积可控（< 20KB）

// 追加一条行为日志（不主动落盘：由调用方此后的 saveData() 统一落盘，避免多余写入）
// type: 'vocab' | 'exam' | 'fav' | 'listen'；ref: 单词 / 题 id / 场景 key；module: 'cet' | 'exam' | ...
function writeActivity(type, ref, module) {
  try {
    if (typeof appData === 'undefined' || !appData) return;
    if (!Array.isArray(appData.activityLog)) appData.activityLog = [];
    appData.activityLog.push({
      t: Date.now(),
      type: type || 'other',
      ref: (ref === null || ref === undefined) ? '' : ref,
      module: module || ''
    });
    if (appData.activityLog.length > ACTIVITY_LOG_MAX) {
      appData.activityLog = appData.activityLog.slice(appData.activityLog.length - ACTIVITY_LOG_MAX);
    }
  } catch (e) { /* 日志写入失败绝不打断主流程 */ }
}

// 相对时间：刚刚 / N 分钟前 / N 小时前 / N 天前 / M月D日
function formatRelTime(ts) {
  try {
    var t = Number(ts) || 0;
    if (!t) return '';
    var diff = Date.now() - t;
    if (diff < 0) diff = 0; // 时钟回拨 / 未来时间戳保护
    var min = Math.floor(diff / 60000);
    if (min < 1) return '刚刚';
    if (min < 60) return min + ' 分钟前';
    var hour = Math.floor(min / 60);
    if (hour < 24) return hour + ' 小时前';
    var day = Math.floor(hour / 24);
    if (day < 30) return day + ' 天前';
    var d = new Date(t);
    return (d.getMonth() + 1) + '月' + d.getDate() + '日';
  } catch (e) { return ''; }
}

// 日期串（YYYY-MM-DD）→ 今天 / 昨天 / N 天前【旧档兼容：lastReview 只有日期，没有时分秒】
function formatDateRel(dateStr) {
  try {
    if (!dateStr || typeof dateStr !== 'string') return '';
    var today = (typeof getTodayStr === 'function') ? getTodayStr() : '';
    if (!today) {
      var n = new Date();
      today = n.getFullYear() + '-' + String(n.getMonth() + 1).padStart(2, '0') + '-' + String(n.getDate()).padStart(2, '0');
    }
    if (dateStr === today) return '今天';
    var d1 = new Date(dateStr + 'T00:00:00');
    var d0 = new Date(today + 'T00:00:00');
    var days = Math.round((d0 - d1) / 86400000);
    if (days <= 0) return '今天'; // 未来/异常日期兜底，不显示负数
    if (days === 1) return '昨天';
    return days + ' 天前';
  } catch (e) { return ''; }
}

// 'YYYY-MM-DD' → epoch ms（本地 0 点），用于旧档按日期排序；非法返回 0
function dateToTs(dateStr) {
  try {
    if (!dateStr || typeof dateStr !== 'string') return 0;
    var p = dateStr.split('-');
    if (p.length < 3) return 0;
    var t = new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2])).getTime();
    return isNaN(t) ? 0 : t;
  } catch (e) { return 0; }
}

// 日志条目 → 首页展示项（找不到题目/无 ref 也要有可读标题，绝不返回 null 之外的异常）
function activityToItem(it) {
  try {
    if (!it) return null;
    var rel = formatRelTime(it.t);
    var type = it.type || '';
    if (type === 'vocab') {
      return { ts: it.t || 0, icon: 'book', title: '背单词 · ' + (it.ref || ''), meta: '四级备考 · ' + rel, module: 'cet' };
    }
    if (type === 'fav') {
      var qf = findExamById(Number(it.ref));
      return { ts: it.t || 0, icon: 'star', title: qf ? (qf.type + '·' + (qf.sub || '')) : ('收藏 · #' + it.ref), meta: '已收藏 · ' + rel, module: 'exam' };
    }
    if (type === 'listen') {
      return { ts: it.t || 0, icon: 'headphones', title: '听力练习 · ' + (it.ref || ''), meta: '四级备考 · ' + rel, module: 'cet' };
    }
    if (type === 'exam') {
      var q = findExamById(Number(it.ref));
      return { ts: it.t || 0, icon: 'package', title: q ? (q.type + '·' + (q.sub || '')) : ('刷题 · #' + it.ref), meta: '央国企笔试 · ' + rel, module: 'exam' };
    }
    // 【批次八】内容库学完记录（markAsViewed 写入，type = viewedContent 的 contentKey）
    var libMeta = {
      commScenes:  { icon: 'message-square', label: '场景话术', meta: '场景话术库 · ', module: 'comm-scenes' },
      commQuotes:  { icon: 'message-square', label: '万能金句', meta: '万能金句库 · ', module: 'comm-quotes' },
      ivQuestions: { icon: 'users',          label: '面试题',   meta: '面试题库 · ',   module: 'iv-questions' },
      pptLayouts:  { icon: 'pen',            label: 'PPT 版式', meta: 'PPT版式库 · ',  module: 'ppt-layouts' },
      etiquette:   { icon: 'users',          label: '商务礼仪', meta: '商务礼仪 · ',   module: 'etiquette' }
    }[type];
    if (libMeta) {
      return { ts: it.t || 0, icon: libMeta.icon, title: libMeta.label + ' · #' + (it.ref || ''), meta: libMeta.meta + rel, module: libMeta.module };
    }
    return { ts: it.t || 0, icon: 'book', title: String(it.ref || '学习记录'), meta: rel, module: it.module || 'cet' };
  } catch (e) { return null; }
}

// 最近学习：① 优先用 activityLog（含 epoch ms → 「3 分钟前」）
//          ② 旧档无日志 → 回退 vocabRecords / examRecords 的 lastReview（YYYY-MM-DD）→「今天/昨天/N 天前」
//          ③ 全空 → []（渲染层走空态），全程不抛异常
function computeRecentLearning() {
  var items = [];
  try {
    var log = (appData && Array.isArray(appData.activityLog)) ? appData.activityLog : [];
    if (log.length) {
      var seen = {};
      log.slice().sort(function (a, b) { return (b.t || 0) - (a.t || 0); }).forEach(function (it) {
        if (!it) return;
        var key = (it.type || '') + '|' + (it.ref === null || it.ref === undefined ? '' : it.ref);
        if (seen[key]) return; // 同一动作（如同做一题）只保留最近一次，避免三行重复
        var d = activityToItem(it);
        if (d) { seen[key] = 1; items.push(d); }
      });
    }
  } catch (e) {}
  if (items.length) return items.slice(0, 3);

  // —— 旧档回退：按 lastReview 日期倒序 ——
  try {
    var vr = (appData && appData.vocabRecords) || {};
    Object.keys(vr).forEach(function (w) {
      var rec = vr[w]; if (!rec) return;
      items.push({
        ts: dateToTs(rec.lastReview),
        icon: 'book',
        title: w,
        meta: '四级词汇 · ' + (formatDateRel(rec.lastReview) || '已学习'),
        module: 'cet'
      });
    });
  } catch (e) {}
  try {
    var er = (appData && appData.examRecords) || {};
    Object.keys(er).forEach(function (id) {
      var rec = er[id]; if (!rec) return;
      var q = findExamById(Number(id));
      items.push({
        ts: dateToTs(rec.lastReview),
        icon: 'package',
        title: q ? (q.type + '·' + (q.sub || '')) : ('题目 #' + id),
        meta: '央国企笔试 · ' + (formatDateRel(rec.lastReview) || '已练习'),
        module: 'exam'
      });
    });
  } catch (e) {}
  try { items.sort(function (a, b) { return (b.ts || 0) - (a.ts || 0); }); } catch (e2) {}
  return items.slice(0, 3);
}

// 在题库中按 id 查找（内置 + 已合并 ext）；找不到返回 null
function findExamById(id) {
  try {
    if (typeof EXAM_BANK !== 'undefined' && EXAM_BANK) {
      for (var i = 0; i < EXAM_BANK.length; i++) if (EXAM_BANK[i].id === id) return EXAM_BANK[i];
    }
  } catch (e) {}
  return null;
}

// T02（批次三 R1-4）：统一空态组件（三件套之 JS 空函数）
// 向 el 注入 .empty-hint 并绑定点击跳对应模块。【后续扩展点：可接入骨架屏/引导卡】
function renderEmptyState(el, moduleKey) {
  if (!el) return;
  el.innerHTML = '';
  var d = document.createElement('div');
  d.className = 'empty-hint';
  if (moduleKey) d.setAttribute('data-module', moduleKey);
  d.textContent = '暂无数据，去开始学习吧 →';
  if (moduleKey) {
    d.onclick = function () { try { navigateTo(moduleKey); } catch (e) {} };
  }
  el.appendChild(d);
}

// 首页「各模块进度」默认展示条数（其余收进「展开全部」，避免首页被 12 张卡撑爆）
const HOME_MODULE_COLLAPSED_COUNT = 6;
var __homeModulesExpanded = false;

// 单张模块卡 HTML：图标 | 名称…百分比 / 通栏进度条 / 通栏「已学 x/y · 正确率 r% · N 前」
function homeModuleCardHtml(m) {
  const st = homeModuleState(m);
  const p = homeModulePercent(m);
  const iconSvg = window.lucideIcon ? window.lucideIcon(m.icon, 20) : '';
  // 百分比位：未开始 / 刚开始 / 真实百分比。数据不足（1~4）显示「刚开始」，绝不显示 NaN
  let pctTxt, muted = '';
  if (st === 'empty') { pctTxt = '未开始'; muted = ' muted'; }
  else if (st === 'few') { pctTxt = '刚开始'; muted = ' muted'; }
  else { pctTxt = p + '%'; }

  // 「已学/总量」：总量未知（异步题库未就位）时只显示已学数，不编造分母
  const totalTxt = (Number(m.total) || 0) > 0 ? (m.done + '/' + m.total) : (m.done + '/—');
  const verb = st === 'empty' ? '共' : (m.unit === '词' ? '已背' : (m.unit === '题' ? '已练' : '已学'));
  let meta = verb + ' ' + totalTxt + ' ' + m.unit;

  const rate = homeModuleRate(m);
  if (rate !== null && st === 'ok') meta += ' · 正确率 ' + rate + '%';
  else if (m.id === 'shenlun' && Number(m.finished) > 0) meta += ' · 已交卷 ' + m.finished + ' 篇';
  if (st === 'few') meta += ' · 刚开始，加油';
  if (st === 'empty') meta = (Number(m.total) || 0) > 0 ? ('共 ' + m.total + ' ' + m.unit + ' · 未开始') : '题库加载中';

  const rel = m.lastTs ? formatRelTime(m.lastTs) : '';
  if (rel) meta += ' · ' + rel;

  // 错题数（行测独有，来自 wrongQuestions 回表统计；0 不显示，避免噪音）
  const wrongN = Number(m.wrong) || 0;
  const wrongHtml = wrongN > 0
    ? `<div class="module-wrong" title="该题型错题 ${wrongN} 道">错题 ${wrongN}</div>` : '';

  const pctCls = 'module-percent' + muted;
  return `
      <div class="module-progress-card" data-module-id="${m.id}" onclick="navigateTo('${m.page}')">
        <div class="module-icon" data-icon="${m.icon}" data-icon-size="18">${iconSvg}</div>
        <div class="module-name">${m.name}</div>
        <div class="${pctCls}">${pctTxt}</div>
        <div class="module-bar"><div class="module-bar-fill" style="width:${p}%"></div></div>
        <div class="module-meta">${meta}</div>
        ${wrongHtml}
      </div>
    `;
}

// 总览条：只汇总同量纲的数据（行测题量/正确率/错题），绝不把「题+词+条」混加
function homeModulesSummaryHtml(all) {
  var xtDone = 0, xtCorrect = 0, xtWrong = 0, xtTotal = 0, started = 0;
  try {
    all.forEach(function (m) {
      if (Number(m.done) > 0) started++;
      if (m.group !== '行测') return;
      xtDone += Number(m.done) || 0;
      xtCorrect += Number(m.correct) || 0;
      xtWrong += Number(m.wrong) || 0;
      xtTotal += Number(m.total) || 0;
    });
  } catch (e) {}
  var rateTxt = xtDone > 0 ? (Math.round(xtCorrect / xtDone * 100) + '%') : '—';
  var totTxt = xtTotal > 0 ? String(xtTotal) : '—';
  return `<div class="module-summary">
      <span class="ms-item"><b>${started}</b> / ${all.length} 个模块已开始</span>
      <span class="ms-item">行测已练 <b>${xtDone}</b> / ${totTxt} 题</span>
      <span class="ms-item">正确率 <b>${rateTxt}</b></span>
      <span class="ms-item${xtWrong > 0 ? ' is-warn' : ''}">错题 <b>${xtWrong}</b> 道</span>
    </div>`;
}

// 分组顺序：行测 → 申论 → 英语 → 内容库 → 其它（兜底，防止新增模块漏展示）
const HOME_MODULE_GROUPS = ['行测', '申论', '英语', '内容库'];

function renderModuleProgress() {
  const grid = document.getElementById('moduleProgressGrid');
  if (!grid) return;
  let all = [];
  try { all = computeHomeModules(); } catch (e) { all = []; }
  // 全空 → 统一空态（不渲染一排 0% 空卡）
  const started = all.filter(m => (Number(m.done) || 0) > 0);
  if (!started.length) {
    renderEmptyState(grid, 'exam-center');
    try { fetchShenlunBankTotalAsync(); } catch (e2) {}
    return;
  }
  // 有进度的在前（按最近学习时间倒序），未开始的按固定顺序补后
  const ordered = started.slice().sort(function (a, b) { return (b.lastTs || 0) - (a.lastTs || 0); })
    .concat(all.filter(m => (Number(m.done) || 0) <= 0));
  const showAll = __homeModulesExpanded || ordered.length <= HOME_MODULE_COLLAPSED_COUNT;
  const show = showAll ? ordered : ordered.slice(0, HOME_MODULE_COLLAPSED_COUNT);

  // 【2026-09-15 重构】按 group 分区渲染：12 个模块平铺会挤爆首屏，
  // 分组后每组自带小标题与组内汇总，行测 5 个题型天然成一组。
  let html = homeModulesSummaryHtml(ordered);
  const buckets = {};
  show.forEach(m => {
    const g = m.group || '其它';
    (buckets[g] = buckets[g] || []).push(m);
  });
  const groupNames = HOME_MODULE_GROUPS.filter(g => buckets[g])
    .concat(Object.keys(buckets).filter(g => HOME_MODULE_GROUPS.indexOf(g) < 0));
  groupNames.forEach(function (g) {
    const list = buckets[g];
    if (!list || !list.length) return;
    const gDone = list.reduce(function (s, m) { return s + (Number(m.done) || 0); }, 0);
    const gTotal = list.reduce(function (s, m) { return s + (Number(m.total) || 0); }, 0);
    const gTip = gTotal > 0 ? (gDone + '/' + gTotal) : (gDone + '/—');
    html += `<div class="module-group">
        <div class="module-group-head"><span class="mg-name">${g}</span><span class="mg-count">${gTip}</span></div>
        <div class="module-group-body">`;
    list.forEach(m => { html += homeModuleCardHtml(m); });
    html += `</div></div>`;
  });

  if (ordered.length > HOME_MODULE_COLLAPSED_COUNT) {
    html += `<div class="module-progress-toggle" onclick="toggleHomeModules()">`
      + (showAll ? '收起 ↑' : ('展开全部 ' + ordered.length + ' 个模块 ↓')) + `</div>`;
  }
  grid.innerHTML = html;
  if (window.lucideAutoRender) { try { window.lucideAutoRender(); } catch (e3) { /* 静默 */ } }
  try { fetchShenlunBankTotalAsync(); } catch (e4) {}
}

// 展开 / 收起全部模块卡
function toggleHomeModules() {
  __homeModulesExpanded = !__homeModulesExpanded;
  try { renderModuleProgress(); } catch (e) { /* 静默 */ }
}

// 申论题库不在首页加载（1.8MB），按需异步取一次条数，成功即缓存并补渲染一次。
// 延迟 1.2s 发起，不与首屏 / 其它题库分片的请求抢带宽。
var __shenlunTotalRequested = false;
function fetchShenlunBankTotalAsync() {
  if (__shenlunTotalRequested) return;
  if (getShenlunBankTotal() > 0) return;
  __shenlunTotalRequested = true;
  try {
    setTimeout(function () {
      try {
        const url = 'assets/data/shenlun-questions.json';
        const p = (typeof fetchJSONAnywhere === 'function') ? fetchJSONAnywhere(url) : fetch(url).then(function (r) { return r.json(); });
        if (!p || typeof p.then !== 'function') return;
        p.then(function (j) {
          var n = (j && j.length) ? j.length : 0;
          if (n <= 0) return;
          try { localStorage.setItem(lsKey('xt_shenlun_total'), String(n)); } catch (e) {}
          try { renderModuleProgress(); } catch (e2) {}
        }).catch(function () { /* 离线 / file:// 取不到：总量留空，卡片显示「已练 N/— 题」 */ });
      } catch (e) { /* 静默 */ }
    }, 1200);
  } catch (e) { /* 静默 */ }
}

function renderWeakPoints() {
  const list = document.getElementById('weakList');
  if (!list) return;
  const wps = computeWeakPoints();
  if (!wps.length) { renderEmptyState(list, 'exam'); return; }
  let html = '';
  wps.forEach(wp => {
    const iconSvg = window.lucideIcon ? window.lucideIcon('alert-triangle', 20) : '';
    html += `
      <div class="weak-item">
        <div class="weak-icon">${iconSvg}</div>
        <div class="weak-info">
          <div class="weak-title">${wp.title}</div>
          <div class="weak-desc">${wp.wrong > 0 ? '正确率 ' + Math.round(wp.rate * 100) + '%，错题 ' + wp.wrong + ' 道，建议专项练习' : '正确率 ' + Math.round(wp.rate * 100) + '%，建议专项练习'}</div>
        </div>
        <div class="weak-action" onclick="navigateTo('${wp.module}')">去练习 →</div>
      </div>
    `;
  });
  list.innerHTML = html;
}

function renderRecentLearning() {
  const list = document.getElementById('recentList');
  if (!list) return;
  const recs = computeRecentLearning();
  if (!recs.length) { renderEmptyState(list, null); return; }
  let html = '';
  recs.forEach(r => {
    const iconSvg = window.lucideIcon ? window.lucideIcon(r.icon, 20) : '';
    html += `
      <div class="recent-item" onclick="navigateTo('${r.module}')">
        <div class="recent-icon">${iconSvg}</div>
        <div class="recent-info">
          <div class="recent-title">${r.title}</div>
          <div class="recent-meta">${r.meta}</div>
        </div>
        <div class="recent-arrow">›</div>
      </div>
    `;
  });
  list.innerHTML = html;
}

// ========== 首页真实数据卡片补渲染（2026-09-15，fix-bug4） ==========
// 背景：renderHome() 只在 app.js 顶层 __tryInit 里跑一次。从模块页返回首页若命中 bfcache
// （脚本不重跑），或用户在另一个标签页学完再切回来，#recentList / #weakList 仍是旧快照，
// 刚写入的 activityLog 看不到。这里不重建 renderHome 调用链，只针对三张真实数据卡片补一次
// 重渲染：先 loadData() 重读 localStorage（跨标签页/跨页面写入），再各渲染一遍，全程 try 兜底。
function refreshHomeCards() {
  var g = document.getElementById('moduleProgressGrid');
  var w = document.getElementById('weakList');
  var r = document.getElementById('recentList');
  if (!g && !w && !r) return;            // 非首页（三容器全无）直接跳过，零副作用
  try { loadData(); } catch (e) { /* 读取失败则沿用现有 appData，不打断 */ }
  if (g) { try { renderModuleProgress(); } catch (e1) { /* 静默 */ } }
  if (w) { try { renderWeakPoints(); } catch (e2) { /* 静默 */ } }
  if (r) { try { renderRecentLearning(); } catch (e3) { /* 静默 */ } }
  if (window.lucideAutoRender) { try { window.lucideAutoRender(); } catch (e4) { /* 静默 */ } }
}
// 绑定开关：只绑一次，避免与其它初始化路径重复注册
var __homeCardsRefreshBound = false;
function bindHomeCardsRefresh() {
  if (__homeCardsRefreshBound) return;
  __homeCardsRefreshBound = true;
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'visible') refreshHomeCards();
  });
  // bfcache / 浏览器后退恢复：persisted=true 时脚本不会重跑，必须手动补渲染
  window.addEventListener('pageshow', function (e) { if (e && e.persisted) refreshHomeCards(); });
  window.addEventListener('focus', refreshHomeCards);
}
if (document.getElementById('page-home')) bindHomeCardsRefresh();

function updateTopbarStats() {
  // 【R37】逐项判空：学习工作台.html 顶栏只有 #streakDays / #todayMinutes，
  // 不存在 #todayTasks / #totalTasks，裸赋值会在 toggleTask 链路抛 TypeError
  setStatText('streakDays', getConvergedStreak()); // T18②：全局口径
  setStatText('todayMinutes', appData.stats.todayMinutes);
  const doneCount = appData.tasks.filter(t => t.done).length;
  setStatText('todayTasks', doneCount);
  setStatText('totalTasks', appData.tasks.length);
}

// ========== 倒计时管理 ==========
let editingCountdownId = null;
let selectedColor = '#5B8DEF';

function openCountdownModal(id) {
  editingCountdownId = id || null;
  const modal = document.getElementById('countdownModal');
  const title = document.getElementById('countdownModalTitle');
  if (id) {
    const cd = appData.countdowns.find(c => c.id === id);
    if (cd) {
      title.textContent = '编辑倒计时';
      document.getElementById('cdName').value = cd.name;
      document.getElementById('cdDate').value = cd.date;
      document.getElementById('cdPinned').checked = cd.pinned;
      selectedColor = cd.color;
    }
  } else {
    title.textContent = '添加倒计时';
    document.getElementById('cdName').value = '';
    document.getElementById('cdDate').value = '';
    document.getElementById('cdPinned').checked = false;
    selectedColor = '#5B8DEF';
  }
  // 更新颜色选择
  document.querySelectorAll('.color-dot').forEach(dot => {
    dot.classList.toggle('active', dot.dataset.color === selectedColor);
  });
  modal.classList.add('active');
}

function closeCountdownModal() {
  document.getElementById('countdownModal').classList.remove('active');
  editingCountdownId = null;
}

function editCountdown(id) {
  openCountdownModal(id);
}

function deleteCountdown(id) {
  uiConfirm('确定要删除这个倒计时吗？', '删除').then(function (ok) {
    if (!ok) return;
    appData.countdowns = appData.countdowns.filter(c => c.id !== id);
    saveData();
    renderCountdowns();
    showToast('已删除');
  });
}

function saveCountdown() {
  const name = document.getElementById('cdName').value.trim();
  const rawDate = document.getElementById('cdDate').value;
  const pinned = document.getElementById('cdPinned').checked;
  if (!name) { showToast('请输入名称'); return; }
  if (!rawDate) { showToast('请选择日期'); return; }
  // T16：入库前规范化（支持 2026-09-20 / 2026.9.20 / 2026年9月20日 等写法），非法则拒绝
  const date = normalizeCountdownDate(rawDate);
  if (!date) { showToast('日期格式不正确'); return; }
  if (editingCountdownId) {
    const cd = appData.countdowns.find(c => c.id === editingCountdownId);
    if (cd) { cd.name = name; cd.date = date; cd.pinned = pinned; cd.color = selectedColor; }
    showToast('已更新');
  } else {
    appData.countdowns.push({
      id: Date.now(),
      name, date, pinned, color: selectedColor
    });
    showToast('已添加');
  }
  saveData();
  renderCountdowns();
  closeCountdownModal();
}

// 颜色选择
document.querySelectorAll('.color-dot').forEach(dot => {
  dot.addEventListener('click', () => {
    document.querySelectorAll('.color-dot').forEach(d => d.classList.remove('active'));
    dot.classList.add('active');
    selectedColor = dot.dataset.color;
  });
});

// 点击遮罩关闭弹窗
var cdmEl = document.getElementById('countdownModal');
if (cdmEl) cdmEl.addEventListener('click', (e) => {
  if (e.target.id === 'countdownModal') closeCountdownModal();
});

// ========== Toast提示 ==========
let toastTimer = null;
// ========== T19（批次三 R6-2/3）：统一弹窗 .app-modal 基础设施（三件套之 JS） ==========
// 行为：ESC 关闭 / 点遮罩关闭 / ✕ 关闭 / 打开锁 body 滚动（overflow:hidden）。
// 约定：弹窗根节点带 class "app-modal-mask"，内部卡片带 class "app-modal"，右上角关闭按钮带 class "app-modal-close"。
// 【后续扩展点：焦点陷阱 / 过渡动画】
function __activeAppModal() { return document.querySelector('.app-modal-mask.active'); }
function openAppModal(id) {
  // 任意被接管弹窗统一锁滚动（#vpMask 等）；带 .app-modal-mask 的弹窗额外加 .active 显示。
  // 【后续扩展点：焦点陷阱 / 过渡动画】
  var m = id ? document.getElementById(id) : null;
  if (!m) return;
  if (m.classList.contains('app-modal-mask')) m.classList.add('active');
  document.body.classList.add('modal-lock');
}
function closeAppModal(id) {
  var m = id ? document.getElementById(id) : __activeAppModal();
  if (!m) m = __activeAppModal();
  if (m) {
    m.classList.remove('active');
    // 仅当无任何其它活跃弹窗（含倒计时 / 听力）时才解锁 body 滚动
    var stillLocked = document.querySelector('.app-modal-mask.active')
      || document.querySelector('.modal-overlay.active')
      || document.getElementById('vpMask');
    if (!stillLocked) document.body.classList.remove('modal-lock');
  }
}
// 全局 ESC 关闭（作用于 .app-modal-mask 与听力播放器 #vpMask）
document.addEventListener('keydown', function (e) {
  if (e.key === 'Escape' || e.keyCode === 27) {
    var m = __activeAppModal();
    if (m) { closeAppModal(); }
    else if (document.getElementById('vpMask') && window.openVoiceTrain) { window.openVoiceTrain.__close(); }
  }
});
// 全局点遮罩关闭（.app-modal-mask 背景 与 听力 #vpMask 背景）
document.addEventListener('click', function (e) {
  var t = e.target;
  if (t && t.classList && t.classList.contains('app-modal-mask')) closeAppModal();
  if (t && t.id === 'vpMask' && window.openVoiceTrain) window.openVoiceTrain.__close();
});

function showToast(msg) {
  const toast = document.getElementById('toast');
  toast.textContent = msg;
  toast.style.transform = 'translateX(-50%) translateY(0)';
  if (toastTimer) clearTimeout(toastTimer);
  toastTimer = setTimeout(() => {
    toast.style.transform = 'translateX(-50%) translateY(-100px)';
  }, 2500);
}

// ========== 深色/浅色主题 ==========
// 主题选择独立保存在 localStorage（key: study_workbench_theme），不与业务数据混存
const THEME_KEY = 'study_workbench_theme';
let themeMode = localStorage.getItem(THEME_KEY) || 'light';
function themePrefersDark() {
  if (themeMode === 'dark') return true;
  if (themeMode === 'auto' && typeof matchMedia !== 'undefined') return matchMedia('(prefers-color-scheme: dark)').matches;
  return false;
}
let isDarkMode = themePrefersDark();
const SKIN_KEY = 'study_workbench_skin';
let currentSkin = localStorage.getItem(SKIN_KEY) || 'default';
function setSkin(name) {
  currentSkin = (name && name !== 'default') ? name : 'default';
  try { localStorage.setItem(SKIN_KEY, currentSkin); } catch (e) { }
  applyTheme();
  if (typeof window.__applySkinUI === 'function') window.__applySkinUI();
}

/**
 * 应用主题到页面（切换 body 的 dark 类 + 配色皮肤 + 更新顶栏按钮图标 + 更新设置页按钮激活态）
 */
function applyTheme() {
  document.body.classList.toggle('dark', isDarkMode);
  ['default', 'violet', 'forest', 'sunset', 'ocean', 'mono', 'rose', 'mint', 'peach', 'lavender', 'amber', 'graphite'].forEach(function (k) {
    document.body.classList.remove('skin-' + k);
  });
  if (currentSkin && currentSkin !== 'default') document.body.classList.add('skin-' + currentSkin);
  // 更新顶栏切换按钮图标（K 批次：🌙/☀️ → moon/sun data-icon）
  const toggleBtn = document.getElementById('themeToggle');
  if (toggleBtn) {
    toggleBtn.innerHTML = '<span class="nav-icon" data-icon="' + (isDarkMode ? 'sun' : 'moon') + '" data-icon-size="20"></span>';
    if (window.lucideAutoRender) window.lucideAutoRender();
  }
  // 更新设置页胶囊按钮激活态
  document.querySelectorAll('#themeOptions .theme-option').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.mode === themeMode);
  });
}

/**
 * 顶栏按钮：在深色/浅色之间来回切换（手动切换会退出“跟随系统”）
 */
function toggleTheme() {
  isDarkMode = !isDarkMode;
  themeMode = isDarkMode ? 'dark' : 'light';
  localStorage.setItem(THEME_KEY, themeMode);
  applyTheme();
  showToast(isDarkMode ? '已切换到深色模式' : '已切换到浅色模式');
}

/**
 * 设置页：指定主题（'light' / 'dark' / 'auto'=跟随系统）
 */
function setTheme(mode) {
  themeMode = (mode === 'auto' || mode === 'dark' || mode === 'light') ? mode : 'light';
  isDarkMode = themePrefersDark();
  try { localStorage.setItem(THEME_KEY, themeMode); } catch (e) { }
  applyTheme();
}

// ========== 数据导出 / 导入 / 清空 ==========
/**
 * 导出：把全部 localStorage 序列化为 JSON 文件
 * - APK 环境：通过 AndroidBridge.saveFile 保存到应用下载目录（WebView 不接管 blob 下载）
 * - 浏览器环境：用 blob + a.click() 下载
 */
function exportData() {
  try {
    // 导出全部 localStorage（不只是 appData，还包括 AI配置/聊天历史/私信/设置等）
    var allData = {};
    for (var i = 0; i < localStorage.length; i++) {
      var key = localStorage.key(i);
      if (!key) continue;
      var raw = localStorage.getItem(key);
      try { allData[key] = JSON.parse(raw); } catch (e) { allData[key] = raw; }
    }
    var exportObj = {
      version: '1.0',
      app: '星途',
      exportedAt: new Date().toISOString(),
      data: allData
    };
    var dataStr = JSON.stringify(exportObj, null, 2);
    var now = new Date();
    var dateStr = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-' + String(now.getDate()).padStart(2, '0');
    var filename = '星途-数据备份-' + dateStr + '.json';

    // APK 环境：原生桥保存文件
    if (window.AndroidBridge && typeof window.AndroidBridge.saveFile === 'function') {
      window.AndroidBridge.saveFile(filename, dataStr, 'application/json');
      showToast('📤 已导出到下载目录：' + filename);
      return;
    }

    // 浏览器环境：blob 下载
    var blob = new Blob([dataStr], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('📤 数据已导出为 JSON 文件');
  } catch (e) {
    showToast('导出失败：' + e.message);
  }
}

/**
 * 导入：读取 JSON 备份文件并恢复数据
 * 支持两种格式：
 * - 新格式 {version, app, data: {key: value, ...}}：恢复全部 localStorage
 * - 旧格式（直接是 appData 对象）：只恢复 appData（合并，不丢失新字段）
 * @param {Event} event - 文件选择框的 change 事件
 */
function importData(event) {
  var file = event.target.files[0];
  if (!file) return;
  var reader = new FileReader();
  reader.onload = function(e) {
    try {
      var imported = JSON.parse(e.target.result);

      // 新格式：恢复全部 localStorage
      if (imported && imported.data && typeof imported.data === 'object') {
        var count = 0;
        var keys = Object.keys(imported.data);
        for (var i = 0; i < keys.length; i++) {
          var k = keys[i];
          var v = imported.data[k];
          localStorage.setItem(k, typeof v === 'string' ? v : JSON.stringify(v));
          count++;
        }
        showToast('📥 导入成功，已恢复 ' + count + ' 项数据，页面即将刷新');
        setTimeout(function() { location.reload(); }, 1200);
        return;
      }

      // 旧格式：只恢复 appData（合并，保留新版本新增字段）
      if (imported && imported.hasOwnProperty && (imported.hasOwnProperty('tasks') || imported.hasOwnProperty('stats'))) {
        appData = Object.assign({}, appData, imported);
        saveData();
        showToast('📥 导入成功（旧格式），页面即将刷新');
        setTimeout(function() { location.reload(); }, 1200);
        return;
      }

      showToast('⚠️ 文件格式不对，请选择本应用导出的备份文件');
    } catch (err) {
      showToast('导入失败：' + err.message);
    }
  };
  reader.readAsText(file, 'utf-8');
  // 清空文件选择框，便于下次选择同一文件也能触发 change
  event.target.value = '';
}

/**
 * 清空：删除全部本地学习数据（双重确认，防误触）
 */
function clearAllData() {
  uiConfirm('确定要清空全部学习数据吗？\n\n此操作不可撤销，建议先导出备份！', '下一步').then(function (ok1) {
    if (!ok1) return;
    return uiConfirm('再次确认：真的要删除全部数据吗？', '删除').then(function (ok2) {
      if (!ok2) return;
      localStorage.removeItem(STORAGE_KEY);
      showToast('数据已清空，页面即将刷新');
      setTimeout(() => location.reload(), 1000);
    });
  });
}

