// ========== 【9/11 新增】每日学习时长统计与上限提醒 ==========
// 口径：页面可见即计时（visibilitychange / blur 暂停），按自然日 key 累计。
// 存储：study_workbench_studytime = { "YYYY-MM-DD": 秒数, ... }（同源 file:// 全页共享）
const STUDY_TIME_KEY = lsKey('study_workbench_studytime');
var _stTick = null;            // 计时器
var _stLast = 0;               // 上次落账时间戳(ms)
var _stWarnedDay = '';         // 已提醒过的日期，避免同一天反复弹

function _stToday() {
  var d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}
function loadStudyTime() {
  try { return JSON.parse(localStorage.getItem(STUDY_TIME_KEY)) || {}; }
  catch (e) { return {}; }
}
function _stSave(obj) {
  try { localStorage.setItem(STUDY_TIME_KEY, JSON.stringify(obj)); } catch (e) { /* 忽略 */ }
}
/** 今日已学秒数 */
function getTodayStudySeconds() {
  var o = loadStudyTime();
  return Math.max(0, Math.round(o[_stToday()] || 0));
}
/** 今日已学「x 小时 y 分钟」文本 */
function getTodayStudyText() {
  var sec = getTodayStudySeconds();
  var h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60);
  if (h <= 0) return m + ' 分钟';
  return h + ' 小时' + (m ? ' ' + m + ' 分钟' : '');
}
/** 累加秒数（内部用） */
function _stAdd(sec) {
  if (sec <= 0) return;
  var o = loadStudyTime();
  var k = _stToday();
  o[k] = Math.max(0, Math.round((o[k] || 0) + sec));
  // 只保留最近 60 天，避免 localStorage 膨胀
  var keys = Object.keys(o).sort();
  if (keys.length > 60) keys.slice(0, keys.length - 60).forEach(function (kk) { delete o[kk]; });
  _stSave(o);
}
/** 重置今日时长（设置页按钮） */
function resetTodayStudyTime() {
  var o = loadStudyTime();
  delete o[_stToday()];
  _stSave(o);
  _stWarnedDay = '';
  syncStudyLimitUI();
  if (typeof showToast === 'function') showToast('✅ 今日学习时长已重置');
}
window.resetTodayStudyTime = resetTodayStudyTime;

/** 落账：把 _stLast 到现在的时间补进今日累计 */
function _stFlush() {
  if (!_stLast) return;
  var now = Date.now();
  var delta = (now - _stLast) / 1000;
  _stLast = now;
  // 单次最多记 5 分钟，防止长时间挂后台被误计
  if (delta > 0 && delta <= 300) _stAdd(delta);
}

/** 是否已超限 */
function isStudyLimitReached() {
  var s = loadAllSettings();
  if (!s.studyLimitOn) return false;
  var limit = (Number(s.studyLimitHours) || 4) * 3600;
  return getTodayStudySeconds() >= limit;
}

/** 超限提醒（每天一次，仅提醒不阻断） */
function checkStudyLimitWarn() {
  if (!isStudyLimitReached()) return;
  var day = _stToday();
  if (_stWarnedDay === day) return;
  _stWarnedDay = day;
  var s = loadAllSettings();
  var tip = '今天已经学习 ' + getTodayStudyText() + ' 啦，超过了你设置的 ' + s.studyLimitHours + ' 小时上限';
  showStudyLimitModal(tip);
  if (typeof showToast === 'function') showToast(tip);
}

/** 超限友好弹窗（自包含，不依赖外部组件；仅提醒不阻断） */
function showStudyLimitModal(desc) {
  var old = document.getElementById('studyLimitModal');
  if (old) old.remove();
  var mask = document.createElement('div');
  mask.id = 'studyLimitModal';
  mask.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:10050;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(2px)';
  mask.onclick = function (e) { if (e.target === mask) mask.remove(); };
  mask.innerHTML =
    '<div style="background:var(--card,#fff);color:var(--text,#1a1b1c);border-radius:20px;max-width:380px;width:100%;padding:26px 24px;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,.3)">' +
    '<div style="font-size:44px;line-height:1;color:var(--primary,#5B8DEF)"><span class="nav-icon" data-icon="moon" data-icon-size="44"></span></div>' +
    '<div style="font-size:19px;font-weight:800;margin-top:10px">今日学习达标啦</div>' +
    '<div style="font-size:14px;color:var(--text-secondary,#6b7280);line-height:1.7;margin-top:10px">' + desc + '</div>' +
    '<div style="font-size:13px;color:var(--text-secondary,#6b7280);line-height:1.7;margin-top:8px">注意劳逸结合，休息好了明天继续加油 💪 继续学习不会被打断～</div>' +
    '<div style="display:flex;gap:10px;margin-top:20px">' +
    '<button id="slmRest" style="flex:1;padding:11px;border:none;border-radius:12px;background:linear-gradient(135deg,var(--primary,#5B8DEF),var(--accent,#8AB4F8));color:#fff;font-size:14px;font-weight:700;cursor:pointer">好的，我去休息</button>' +
    '<button id="slmGo" style="flex:1;padding:11px;border:1px solid var(--border,#e4e3dd);border-radius:12px;background:transparent;color:var(--text,#1a1b1c);font-size:14px;font-weight:600;cursor:pointer">再学一会儿</button>' +
    '</div></div>';
  document.body.appendChild(mask);
  if (window.lucideAutoRender) window.lucideAutoRender(); // 动态插入的 moon 图标重渲染
  var close = function () { mask.remove(); };
  document.getElementById('slmRest').onclick = close;
  document.getElementById('slmGo').onclick = close;
}
window.showStudyLimitModal = showStudyLimitModal;

/** 启动计时（各页 init 调用；重复调用安全） */
function initStudyTimer() {
  if (_stTick) return;
  _stLast = document.visibilityState === 'hidden' ? 0 : Date.now();
  // 每 15 秒落账一次（低开销）
  _stTick = setInterval(function () {
    if (document.visibilityState !== 'hidden') {
      _stFlush();
      checkStudyLimitWarn();
      syncStudyLimitUI();
    }
  }, 15000);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') {
      _stFlush(); _stLast = 0;
    } else {
      _stLast = Date.now();
    }
  });
  window.addEventListener('pagehide', function () { _stFlush(); _stLast = 0; });
  window.addEventListener('beforeunload', function () { _stFlush(); });
  syncStudyLimitUI();
}
window.initStudyTimer = initStudyTimer;

/** 同步设置页/个人中心的时长 UI（元素不存在则跳过） */
function syncStudyLimitUI() {
  var sec = getTodayStudySeconds();
  var s = loadAllSettings();
  var limit = (Number(s.studyLimitHours) || 4) * 3600;
  var pct = limit > 0 ? Math.min(100, Math.round(sec / limit * 100)) : 0;
  var h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60);
  var over = sec >= limit;
  var bar = document.getElementById('stLimitBar');
  if (bar) {
    bar.style.width = pct + '%';
    bar.style.background = over
      ? 'linear-gradient(90deg,#F87171,#EF4444)'
      : 'linear-gradient(90deg,var(--primary),var(--accent))';
  }
  var d = document.getElementById('stLimitTodayDesc');
  if (d) d.textContent = '今日已学 ' + h + ' 小时 ' + m + ' 分钟 / 上限 ' + (s.studyLimitHours || 4) + ' 小时' + (over ? '（已达标 🎉）' : '');
  var tip = document.getElementById('stLimitTip');
  if (tip) {
    if (!s.studyLimitOn) tip.textContent = '已关闭上限提醒，仍会照常统计今日时长。';
    else if (over) tip.textContent = '已超过今日上限，注意休息；继续学习不会被打断。';
    else tip.textContent = '距离上限还有 ' + Math.max(0, Math.floor((limit - sec) / 60)) + ' 分钟。';
  }
  // 个人中心卡片（若存在）
  var pc = document.getElementById('pcStudyTime');
  if (pc) pc.textContent = getTodayStudyText();
  var pcBar = document.getElementById('pcStudyTimeBar');
  if (pcBar) pcBar.style.width = pct + '%';
  var pcTip = document.getElementById('pcStudyTimeTip');
  if (pcTip) pcTip.textContent = s.studyLimitOn ? ('上限 ' + (s.studyLimitHours || 4) + ' 小时 · 已完成 ' + pct + '%') : ('今日已学 ' + getTodayStudyText());
}
window.syncStudyLimitUI = syncStudyLimitUI;
window.getTodayStudySeconds = getTodayStudySeconds;
window.getTodayStudyText = getTodayStudyText;

/** 设置页控件回填（HTML 里 select/checkbox 的默认选中值与存储值可能不一致，这里统一同步）*/
function seedStudyLimitUI() {
  var s = loadAllSettings();
  var on = document.getElementById('stLimitOn');
  if (on) on.checked = !!s.studyLimitOn;
  var sel = document.getElementById('stLimitHours');
  if (sel) sel.value = String(s.studyLimitHours || 4);
  syncStudyLimitUI();
}
window.seedStudyLimitUI = seedStudyLimitUI;

/* =====================================================================
   【R60】全站入站消息通知（微信 / QQ 式右上角弹窗 + 导航未读红点）
   ---------------------------------------------------------------------
   app.js 全站每页都加载，而 chat-local.js 只在 私聊.html 加载 —— 这是
   「其他页面收不到消息通知」的根因。这里补一个全局层：
     · window.xtNotifyMessage(msg)  右上角通知（右侧滑入 + 淡入，4 秒自动消失）
     · window.xtSetUnread(n)        底部导航 / 侧边栏「消息 / 好友」入口未读红点
     · 全局轮询 /api/chat/unread（8s，页面不可见时跳过）
   跨线契约：私聊页（chat-local.js）已开连接时会置 window.__xtChatTransportActive = true，
   此时本层不再开第二条轮询，只作为被调方（对端会 typeof 判空后调用本文件的两个函数）。
   注：两个函数一旦定义即全局可用，且都做了入参容错（缺字段不抛异常）。

   【后续扩展点】本期不做：
     P1 系统级通知（Notification API 授权 + 后台推送）；
     P2 新消息提示音 / 多标签页已读同步（BroadcastChannel 或 storage 事件）。
   ===================================================================== */
(function initGlobalMessageNotify() {
  var XT_TOAST_MAX = 4;      // 最多同时堆叠 4 条，超出排队
  var XT_TOAST_MS = 4000;    // 自动消失时间
  var XT_POLL_MS = 8000;     // 未读轮询间隔

  var wrap = null;           // .msg-toast-wrap 容器（懒建）
  var live = [];             // 当前在屏的 toast
  var queue = [];            // 排队等待的 toast
  var seen = {};             // peerId:lastId → true，避免同一条消息反复弹
  var baselineReady = false; // 首次轮询只建基线，不弹历史未读

  function xtEsc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function xtRaf(cb) {
    if (window.requestAnimationFrame) return window.requestAnimationFrame(cb);
    return setTimeout(cb, 16);
  }

  function ensureWrap() {
    if (wrap && wrap.parentNode) return wrap;
    wrap = document.getElementById('xtToastWrap');
    if (!wrap) {
      wrap = document.createElement('div');
      wrap.id = 'xtToastWrap';
      wrap.className = 'msg-toast-wrap';
      document.body.appendChild(wrap);
    }
    return wrap;
  }

  /* 关闭并移除一条 toast，然后从队列里补一条进来 */
  function closeToast(item) {
    if (!item || item.closed) return;
    item.closed = true;
    if (item.timer) { clearTimeout(item.timer); item.timer = null; }
    var idx = live.indexOf(item);
    if (idx >= 0) live.splice(idx, 1);
    if (item.el) {
      item.el.classList.remove('show');
      var el = item.el;
      setTimeout(function () { if (el && el.parentNode) el.parentNode.removeChild(el); }, 320);
    }
    drainQueue();
  }

  function drainQueue() {
    while (live.length < XT_TOAST_MAX && queue.length) {
      var item = queue.shift();
      if (item) mountToast(item);
    }
  }

  function scheduleClose(item) {
    if (item.timer) { clearTimeout(item.timer); item.timer = null; }
    item.startedAt = Date.now();
    item.timer = setTimeout(function () { closeToast(item); }, item.remaining);
  }

  function mountToast(item) {
    var host = ensureWrap();
    var el = document.createElement('div');
    el.className = 'msg-toast';
    el.setAttribute('role', 'alert');
    var title = xtEsc(item.title || '新消息');
    var text = xtEsc(item.text || '');
    var avatar = item.avatar
      ? '<img class="msg-toast-av" src="' + xtEsc(item.avatar) + '" alt="">'
      : '<span class="msg-toast-av msg-toast-av-txt">' + xtEsc((item.title || '新').slice(0, 1)) + '</span>';
    el.innerHTML =
      avatar +
      '<span class="msg-toast-body">' +
        '<span class="msg-toast-title">' + title + '</span>' +
        '<span class="msg-toast-text">' + text + '</span>' +
      '</span>' +
      '<span class="msg-toast-close" title="关闭">×</span>';
    host.appendChild(el);
    item.el = el;
    live.push(item);

    // 下一帧加 .show 触发滑入 + 淡入（老 WebView 无 rAF 时回退 setTimeout）
    xtRaf(function () { xtRaf(function () { el.classList.add('show'); }); });

    // hover 暂停倒计时，移出后按剩余时间继续
    el.addEventListener('mouseenter', function () {
      if (item.timer) { clearTimeout(item.timer); item.timer = null; }
      if (item.remaining > 0) item.remaining -= Math.max(0, Date.now() - (item.startedAt || Date.now()));
    });
    el.addEventListener('mouseleave', function () { if (!item.closed) scheduleClose(item); });

    el.querySelector('.msg-toast-close').addEventListener('click', function (e) {
      e.stopPropagation();
      closeToast(item);
    });
    el.addEventListener('click', function () {
      closeToast(item);
      gotoChatWith(item.peerId, item.title, item.avatar);
    });

    item.remaining = XT_TOAST_MS;
    scheduleClose(item);
  }

  /* 沿用站内现有跳转：私聊页深链 ?uid=&name=（chat-local.js maybeAutoOpenChat 消费）；
     已在私聊页则直接调 imOpenChatWithUser 打开会话。绝不发明新路由。 */
  function gotoChatWith(peerId, name, avatar) {
    var uid = Number(peerId);
    if (!uid) { if (typeof gotoChat === 'function') gotoChat(); return; }
    if (typeof window.imOpenChatWithUser === 'function') {
      try { window.imOpenChatWithUser(uid, name || '', avatar || ''); return; } catch (e) { /* 落到深链 */ }
    }
    location.href = '私聊.html?uid=' + uid + '&name=' + encodeURIComponent(name || '');
  }

  /**
   * 弹一条入站消息通知。
   * msg: { senderId/peerId, senderName/nickname/name, avatar, text/content/last, lastId }
   * 与当前聊天对象相同（window.currentChatUserId）时不弹；超出上限自动排队。
   */
  function xtNotifyMessage(msg) {
    try {
      msg = msg || {};
      var peerId = msg.senderId != null ? msg.senderId : msg.peerId;
      if (peerId == null) return;
      if (window.currentChatUserId != null && String(peerId) === String(window.currentChatUserId)) return; // 正在跟对方聊：不打扰
      var name = msg.senderName || msg.nickname || msg.name || ('用户' + peerId);
      var text = msg.text != null ? msg.text : (msg.content != null ? msg.content : (msg.last || ''));
      var item = {
        peerId: peerId,
        title: name,
        text: String(text).slice(0, 120),
        avatar: msg.avatar || '',
        remaining: XT_TOAST_MS
      };
      if (live.length < XT_TOAST_MAX) mountToast(item);
      else queue.push(item);
    } catch (e) { /* 通知失败绝不影响主流程 */ }
  }

  /**
   * 给底部导航 / 侧边栏的「消息 / 好友 / 互动」入口注入未读红点（数字）。
   * 纯 JS 注入，不逐页改 HTML；n<=0 时隐藏。
   */
  function xtSetUnread(n) {
    try {
      n = Number(n) || 0;
      window.__xtUnread = n;
      var label = n > 99 ? '99+' : String(n);
      var nodes = document.querySelectorAll('.nav-item[onclick*="gotoChat"], .bottom-nav-item[onclick*="gotoChat"], .nav-item[data-page="friends"], .nav-item[data-page="chat"]');
      for (var i = 0; i < nodes.length; i++) {
        var node = nodes[i];
        var b = node.querySelector('.xt-unread-badge');
        if (n <= 0) {
          if (b && b.parentNode) b.parentNode.removeChild(b);
          continue;
        }
        if (!b) {
          b = document.createElement('span');
          b.className = 'xt-unread-badge';
          node.appendChild(b);
        }
        b.textContent = label;
        // 徽标绝对定位，父级需要非 static 定位（侧边栏 .nav-item 已是 relative）
        if (window.getComputedStyle) {
          var pos = window.getComputedStyle(node).position;
          if (pos === 'static') node.style.position = 'relative';
        } else {
          node.style.position = 'relative';
        }
      }
    } catch (e) { /* 静默 */ }
  }

  window.xtNotifyMessage = xtNotifyMessage;
  window.xtSetUnread = xtSetUnread;
  window.xtCloseAllToasts = function () { live.slice().forEach(closeToast); };

  /* ---------- 全局未读轮询（私聊页已开连接时不启动第二条） ---------- */
  function xtApiBase() {
    return (window.STUDY_API_BASE != null ? window.STUDY_API_BASE
      : ((location.protocol === 'http:' || location.protocol === 'https:') ? '' : 'http://110.42.134.62:8000'));
  }
  function xtToken() { try { return localStorage.getItem('study_workbench_token'); } catch (e) { return ''; } }

  function xtPollUnread() {
    var token = xtToken();
    if (!token) return;
    if (window.__xtChatTransportActive === true) return;   // 私聊页已自己轮询
    if (document.visibilityState && document.visibilityState !== 'visible') return;
    fetch(xtApiBase() + '/api/chat/unread', { headers: { 'Authorization': 'Bearer ' + token } })
      .then(function (r) { return r.json(); })
      .then(function (d) {
        var items = (d && d.items) || [];
        var total = 0, need = [];
        items.forEach(function (it) {
          var cnt = Number(it.count) || 0;
          total += cnt;
          var key = String(it.peerId) + ':' + String(it.lastId || '');
          if (cnt > 0 && !seen[key]) { seen[key] = true; need.push(it); }
        });
        if (typeof d.total === 'number' && d.total > total) total = d.total;
        xtSetUnread(total);
        if (!baselineReady) { baselineReady = true; return; }  // 首次只建基线，不弹历史未读
        need.forEach(function (it) {
          xtNotifyMessage({
            senderId: it.peerId,
            senderName: it.nickname || it.name || ('用户' + it.peerId),
            avatar: it.avatar || '',
            text: it.last || '',
            lastId: it.lastId
          });
        });
      })
      .catch(function () { /* 离线 / 未登录：静默 */ });
  }

  function xtStartPoll() {
    if (window.__xtPollStarted) return;
    window.__xtPollStarted = true;
    xtPollUnread();
    setInterval(xtPollUnread, XT_POLL_MS);
  }

  // 页面可见性恢复时立刻补一次，避免切回前台要等一个轮询周期
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'visible') xtPollUnread();
  });

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', xtStartPoll);
  else xtStartPoll();
})();
